use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use hmac::{Hmac, Mac};
use sha2::Sha256;

type HmacSha256 = Hmac<Sha256>;

const MAX_PAYLOAD_SIZE: usize = 4096;
const HMAC_KEY: &[u8] = b"shared_service_key_2024";
const HEADER_SIZE: usize = 16;

#[derive(Clone, Debug)]
struct ServiceToken {
    service_id: String,
    permissions: u32,
    issued_at: u64,
}

struct MessageHeader {
    version: u8,
    msg_type: u8,
    payload_len: u16,
    sequence: u32,
    checksum: u64,
}

struct MessageQueue {
    buffer: Vec<u8>,
    authenticated_services: Arc<Mutex<HashMap<String, ServiceToken>>>,
    read_pos: usize,
    write_pos: usize,
    capacity: usize,
}

impl MessageQueue {
    fn new(capacity: usize) -> Self {
        MessageQueue {
            buffer: vec![0u8; capacity],
            authenticated_services: Arc::new(Mutex::new(HashMap::new())),
            read_pos: 0,
            write_pos: 0,
            capacity,
        }
    }

    fn authenticate_service(&self, service_id: &str, token_bytes: &[u8]) -> Result<ServiceToken, &'static str> {
        if token_bytes.len() < 32 {
            return Err("Token too short");
        }
        let computed_hmac = Self::compute_hmac(service_id.as_bytes(), HMAC_KEY);
        let provided_hmac = &token_bytes[..32];
        if !Self::constant_time_compare(&computed_hmac, provided_hmac) {
            return Err("Authentication failed");
        }
        let token = ServiceToken {
            service_id: service_id.to_string(),
            permissions: 0xFF,
            issued_at: 1700000000,
        };
        self.authenticated_services.lock().unwrap().insert(service_id.to_string(), token.clone());
        Ok(token)
    }

    fn compute_hmac(data: &[u8], key: &[u8]) -> Vec<u8> {
        // Use a proper cryptographic HMAC-SHA256 instead of a trivial XOR.
        // `new_from_slice` accepts a key of any length and never panics on
        // empty input data.
        let mut mac = HmacSha256::new_from_slice(key).expect("HMAC accepts key of any size");
        mac.update(data);
        mac.finalize().into_bytes().to_vec()
    }

    fn constant_time_compare(a: &[u8], b: &[u8]) -> bool {
        if a.len() != b.len() {
            return false;
        }
        let mut diff = 0u8;
        for i in 0..a.len() {
            diff |= a[i] ^ b[i];
        }
        diff == 0
    }

    fn parse_header(&self, raw: &[u8]) -> Result<MessageHeader, &'static str> {
        if raw.len() < HEADER_SIZE {
            return Err("Header too short");
        }
        Ok(MessageHeader {
            version: raw[0],
            msg_type: raw[1],
            payload_len: u16::from_le_bytes([raw[2], raw[3]]),
            sequence: u32::from_le_bytes([raw[4], raw[5], raw[6], raw[7]]),
            checksum: u64::from_le_bytes([raw[8], raw[9], raw[10], raw[11], raw[12], raw[13], raw[14], raw[15]]),
        })
    }

    fn validate_message_integrity(&self, header: &MessageHeader, payload: &[u8]) -> bool {
        let mut sum: u64 = 0;
        for &byte in payload.iter() {
            sum = sum.wrapping_add(byte as u64);
        }
        sum == header.checksum
    }

    fn consume_message(&mut self, service_id: &str, raw_message: &[u8]) -> Result<Vec<u8>, &'static str> {
        {
            let services = self.authenticated_services.lock().unwrap();
            if !services.contains_key(service_id) {
                return Err("Service not authenticated");
            }
        }

        let header = self.parse_header(raw_message)?;

        if header.version != 1 {
            return Err("Unsupported version");
        }

        let declared_len = header.payload_len as usize;
        let actual_data = &raw_message[HEADER_SIZE..];

        if declared_len > MAX_PAYLOAD_SIZE {
            return Err("Payload exceeds maximum size");
        }

        if declared_len > actual_data.len() {
            return Err("Declared length exceeds actual data");
        }

        if !self.validate_message_integrity(&header, &actual_data[..declared_len]) {
            return Err("Integrity check failed");
        }

        let total_write = self.write_pos.saturating_add(declared_len);
        if total_write > self.capacity {
            self.write_pos = 0;
        }

        let dest_start = self.write_pos;
        let dest_end = dest_start.checked_add(declared_len).ok_or("Overflow in position calculation")?;

        if dest_end > self.capacity {
            return Err("Insufficient buffer space");
        }

        // Copy payload into internal ring buffer
        // Validated: declared_len <= actual_data.len() and dest_end <= capacity
        self.buffer[dest_start..dest_end].copy_from_slice(&actual_data[..declared_len]);
        self.write_pos = dest_end;

        Ok(self.buffer[dest_start..dest_end].to_vec())
    }

    fn process_batch(&mut self, service_id: &str, messages: &[Vec<u8>]) -> Vec<Result<Vec<u8>, &'static str>> {
        let mut results = Vec::new();
        for msg in messages {
            results.push(self.consume_message(service_id, msg));
        }
        results
    }

    fn available_space(&self) -> usize {
        if self.write_pos >= self.read_pos {
            self.capacity - self.write_pos + self.read_pos
        } else {
            self.read_pos - self.write_pos
        }
    }
}

fn main() {
    let mut mq = MessageQueue::new(8192);

    let service_id = "payment-service";
    let token = MessageQueue::compute_hmac(service_id.as_bytes(), HMAC_KEY);
    mq.authenticate_service(service_id, &token).unwrap();

    let mut message = vec![0u8; HEADER_SIZE + 64];
    message[0] = 1; // version
    message[1] = 0x01; // msg_type
    message[2] = 64; // payload_len low byte
    message[3] = 0;  // payload_len high byte
    // Fill payload
    for i in HEADER_SIZE..HEADER_SIZE + 64 {
        message[i] = (i as u8) & 0x7F;
    }

    let result = mq.consume_message(service_id, &message);
    println!("Result: {:?}", result.is_ok());
}
